   if(!refund.purpose().equals(identity.get("purpose"))||!refund.claimId().equals(claim)||!refund.orderId().equals(order)||!refund.sellerOrderId().equals(row.get("seller_order_id"))||refund.version()<version||refund.amount()!=((Number)row.get(refund.purpose().equals("ITEM")?"item_amount":"original_shipping")).longValue()) { throw new OrderRejected(409); }
